// Calculate material costs based on project specifications
const projectData = $input.first().json.project_data;
const loadCalculation = $input.first().json.load_calculation;
const serviceCalculation = $input.first().json.service_calculation;
const components = $input.all().slice(1); // Skip first item which is project data

// Basic material estimation based on square footage and building type
let materialCost = 0;
let laborCost = 0;
let componentList = [];

const squareFootage = projectData.square_footage || 1000;
const buildingType = projectData.building_type || 'residential';

// Calculate based on typical electrical densities
const densityMultipliers = {
  residential: 3.5, // $3.50 per sq ft
  commercial: 5.5,  // $5.50 per sq ft
  industrial: 4.0   // $4.00 per sq ft
};

const baseCostPerSqFt = densityMultipliers[buildingType] || 3.5;
materialCost = squareFootage * baseCostPerSqFt;

// Labor is typically 40-60% of material cost for electrical work
laborCost = materialCost * 0.5;

// Add service upgrade costs if needed
if (serviceCalculation && serviceCalculation.recommendedServiceSize > 100) {
  const serviceUpgradeCost = (serviceCalculation.recommendedServiceSize - 100) * 5;
  materialCost += serviceUpgradeCost;
  laborCost += serviceUpgradeCost * 0.4;
}

// Equipment costs (panels, breakers, etc.)
const equipmentCost = materialCost * 0.2;

// Total project cost with markup
const totalCost = (materialCost + laborCost + equipmentCost) * 1.15; // 15% markup

// Calculate confidence score based on data completeness
let confidenceScore = 70; // Base confidence
if (projectData.square_footage) confidenceScore += 10;
if (projectData.project_specifications) confidenceScore += 10;
if (loadCalculation && serviceCalculation) confidenceScore += 10;

return [{
  project_id: $input.first().json.project_id,
  estimation_id: $input.first().json.estimation_id,
  calculations: {
    load_calculation: loadCalculation,
    service_calculation: serviceCalculation,
    material_breakdown: {
      base_material: materialCost,
      labor: laborCost,
      equipment: equipmentCost,
      markup_percentage: 15
    }
  },
  material_cost: Math.round(materialCost),
  labor_cost: Math.round(laborCost),
  equipment_cost: Math.round(equipmentCost),
  total_cost: Math.round(totalCost),
  confidence_score: Math.min(confidenceScore, 100),
  status: 'completed',
  accuracy_level: 'preliminary'
}];
